  if (printerPanel) {
    const session = state.session;
    const printerAction = (action: string) => client.send('printer_action', { action });
    // No tool closes the panel for the model: the person decides when they
    // are done, with Back, Done or by opening the printer's own settings.
    // The model offers Done alone once nothing is left to decide (FINISHING
    // in printerInstructions.ts); while it is offered there is no
    // conversation left to lose, so neither Done nor Back asks, unless words
    // or a photo wait to be sent. Done beside other choices, such as "Done |
    // I need help" while connecting, answers a step and is sent as a reply.
    const choices = openChoices(state.messages);
    const doneOffered = choices.length === 1 && choices[0] === DONE_CHOICE;
    const back = () => {
      const unsent = state.attachments.some((attachment) => attachment.state === 'staged') ||
        printerDraft.current.trim() !== '';
      if (unsent || (started && !doneOffered)) setConfirmPrinterClose(true);
      else printerAction('close');
    };
    return (
      // The whole panel takes a photo, not only the composer: a picture of
      // the printer is dropped where the person is looking.
      <div
        className="app app--printer app--printer-setup"
        onDragOver={(event) => event.preventDefault()}
        onDrop={(event) => {
          const files = Array.from(event.dataTransfer.files ?? []);
          if (files.length === 0) return;
          event.preventDefault();
          attachFiles(files, 'drop');
        }}
      >
        {errorNotice}
        <TaskHeader title={printerTaskTitle(session)} onClose={back}>
          <button type="button" className="panel-link-button" onClick={() => printerAction(session?.printerName ? 'open_printer_settings' : 'manual_setup')}>
            {session?.printerName ? 'Open printer settings' : 'Browse the full printer list'}
          </button>
        </TaskHeader>
        <div className="chat-content">
          {session?.form && (
            <AddPrinterForm
              form={session.form}
              onAsk={(catalogId, nozzle) => client.send('printer_action', { action: 'form_options', catalogId, nozzle })}
              onFinish={(choice) => client.send('printer_action', { action: 'form_finish', ...choice })}
              onClose={() => printerAction('form_close')}
            />
          )}
          {confirmPrinterClose && (
            <Dialog title="Close this chat?" onClose={() => setConfirmPrinterClose(false)}>
              <p>Printers already added stay added. The chat can't be opened again.</p>
              <div className="chat-dialog-buttons">
                <button type="button" onClick={() => setConfirmPrinterClose(false)}>Cancel</button>
                <button type="button" className="danger decisive" onClick={() => { setConfirmPrinterClose(false); printerAction('close'); }}>
  // file on macOS whatever `accept` says.
  const pickFiles = (choice: (typeof ATTACHMENT_CHOICES)[number]) => {
    if (onPickFiles) {
      onPickFiles(choice.kind);
      return;
    }
    if (!fileInput.current) return;
    fileInput.current.accept = choice.accept;
    fileInput.current.click();
  };

  const handleFiles = (files: FileList | null, source: AttachmentSource) => {
    if (!files || files.length === 0) return;
    onAttachFiles(Array.from(files), source);
  };

  const handlePickerChange = (event: ChangeEvent<HTMLInputElement>) => {
    handleFiles(event.target.files, 'picker');
    event.target.value = ''; // allow re-picking the same file
  };

  const handlePaste = (event: ClipboardEvent<HTMLTextAreaElement>) => {
    const files = Array.from(event.clipboardData.files ?? []);
    if (files.length > 0) {
      event.preventDefault();
      onAttachFiles(files, 'clipboard');
    }
  };

  const handleDrop = (event: DragEvent<HTMLDivElement>) => {
    event.preventDefault();
    setDragging(false);
    if (disabled) return;
    handleFiles(event.dataTransfer.files, 'drop');
  };

  return (
    <div
      className={`composer${dragging ? ' dragging' : ''}`}
      onDragOver={(event) => {
        event.preventDefault();
        if (!disabled) setDragging(true);
      }}
      onDragLeave={() => setDragging(false)}
      onDrop={handleDrop}
    >
      {notice}
      {block && <div className="composer-credits" role="status">
        <span>{block}</span>
        <div className="composer-credits-actions">
          <button type="button" className="link" onClick={() => credits?.onGetMore()}>Get more credits</button>
        </div>
      </div>}
      {!!credits?.creditsAdded && !block && <div className="composer-credits composer-credits--added" role="status">
        +{creditCount(credits.creditsAdded)}
      </div>}
      {lowShown && <div className="composer-credits composer-credits--low" role="status">
        <span>{low}</span>
        <button type="button" className="link" onClick={() => credits?.onGetMore()}>Get more credits</button>
        <button type="button" className="composer-credits-close" aria-label="Close" onClick={() => credits?.onLowNoticeDone()}>
          <span className="jp-icon jp-icon-close" aria-hidden="true" />
