import { StrictMode } from 'react';
import { createRoot } from 'react-dom/client';
import { App } from './App';
import { PreferencesApp } from './PreferencesApp';
import { OrcaImportApp } from './OrcaImportApp';
import { GuideApp } from './GuideApp';
import { nativeTransport } from './bridge/client';
import { installDropGuard } from './bridge/dropGuard';
import { applyAppearance, applyStaticTokens } from './tokens';
import './styles.css';

applyStaticTokens();
applyAppearance('light');
installDropGuard(window);

const query = new URLSearchParams(window.location.search);
// The temporary printer task chat loads the same page with ?panel=printer: the same
// thread and composer, with the printer session's card pinned above them
// instead of the project's setup card. See App.tsx.
const panel = query.get('panel') === 'printer';
// JusPrin's Preferences window loads it with ?panel=preferences: its own
// surface, drawn with the same Agent connection rows. See PreferencesApp.tsx.
const preferences = query.get('panel') === 'preferences';
// File › Import › Import from OrcaSlicer…'s and Import from JusPrin 1…'s window loads it with
// ?panel=orca-import. See OrcaImportApp.tsx.
const orcaImport = query.get('panel') === 'orca-import';
// Help › JusPrin guide…'s window loads it with ?panel=guide. See GuideApp.tsx.
const guide = query.get('panel') === 'guide';

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    {preferences
      ? <PreferencesApp getTransport={nativeTransport} />
      : orcaImport
        ? <OrcaImportApp getTransport={nativeTransport} />
        : guide
          ? <GuideApp getTransport={nativeTransport} />
          : <App getTransport={nativeTransport} printerPanel={panel} />}
  </StrictMode>,
);

// What the web view does with a drag the page leaves alone: every engine the
// app embeds (WKWebView, WebView2, WebKitGTK) opens a dropped file or link in
// place of the page, so a picture dropped beside the composer replaced the
// whole chat. A part of the page that takes a drop cancels the event itself;
// this catches the rest after them. A text field keeps its own drop of text
// or a link; a file is never opened in place, wherever it lands.

function editable(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return target instanceof HTMLTextAreaElement || target instanceof HTMLInputElement || target.isContentEditable;
}

function guard(event: DragEvent): void {
  if (event.defaultPrevented) return;
  const files = event.dataTransfer?.types.includes('Files') ?? false;
  if (!files && editable(event.target)) return;
  event.preventDefault();
  if (event.dataTransfer) event.dataTransfer.dropEffect = 'none';
}

export function installDropGuard(target: Window): () => void {
  target.addEventListener('dragover', guard);
  target.addEventListener('drop', guard);
  return () => {
    target.removeEventListener('dragover', guard);
    target.removeEventListener('drop', guard);
  };
}

