static void poll(void) {
    NSString *cmdPath = [gDir stringByAppendingPathComponent:@"cmd.txt"];
    NSString *cmd = [NSString stringWithContentsOfFile:cmdPath encoding:NSUTF8StringEncoding error:nil];
    if (cmd.length) {
        [[NSFileManager defaultManager] removeItemAtPath:cmdPath error:nil];
        for (NSString *line in [cmd componentsSeparatedByString:@"\n"]) {
            NSArray *p = [line componentsSeparatedByString:@"\t"];
            if ([p[0] isEqualToString:@"list"]) {
                for (WKWebView *wv in webviews())
                    logline([NSString stringWithFormat:@"list: %@ visible=%d frame=%@", wv.URL.absoluteString, wv.window.isVisible && !wv.isHiddenOrHasHiddenAncestor, NSStringFromRect([wv convertRect:wv.bounds toView:nil])]);
            } else if ([p[0] isEqualToString:@"drop"] && p.count >= 5) {
                doDrop(p[1], p[2], [p[3] doubleValue], [p[4] doubleValue], YES);
            } else if ([p[0] isEqualToString:@"hover"] && p.count >= 5) {
                doDrop(p[1], p[2], [p[3] doubleValue], [p[4] doubleValue], NO);
            } else if ([p[0] isEqualToString:@"snap"] && p.count >= 3) {
                WKWebView *wv = nil;
                for (WKWebView *w in webviews()) if (w.window.isVisible && !w.isHiddenOrHasHiddenAncestor && w.bounds.size.width > 100 && [w.URL.absoluteString containsString:p[1]]) wv = w;
                NSString *out = p[2];
                if (!wv) { logline(@"snap: none"); continue; }
                [wv takeSnapshotWithConfiguration:nil completionHandler:^(NSImage *img, NSError *e) {
                    NSBitmapImageRep *rep = [[NSBitmapImageRep alloc] initWithData:img.TIFFRepresentation];
                    [[rep representationUsingType:NSBitmapImageFileTypePNG properties:@{}] writeToFile:out atomically:YES];
                    logline([NSString stringWithFormat:@"snap: %@ %@", out, e ? e.localizedDescription : @"ok"]);
                }];
            } else if ([p[0] isEqualToString:@"trace"]) {
                installTrace();
            } else if ([p[0] isEqualToString:@"js"] && p.count >= 3) {
                doJs(p[1], p[2]);
            }
        }
    }
    dispatch_after(dispatch_time(DISPATCH_TIME_NOW, 300 * NSEC_PER_MSEC), dispatch_get_main_queue(), ^{ poll(); });
}

