#include "slic3r/GUI/I18N.hpp"
#include "slic3r/GUI/JusPrin/Shell/McpSetupCommand.hpp"
#include "slic3r/GUI/JusPrin/Shell/ShellRecipes.hpp"
#include "slic3r/GUI/JusPrin/Workspace/Workspace.hpp"
#include "slic3r/GUI/Widgets/Button.hpp"
#include "slic3r/GUI/Widgets/WebView.hpp"

#include <boost/filesystem.hpp>
#include <boost/log/trivial.hpp>

#include <cstdlib>
#include <memory>
#include <utility>

#include <wx/filedlg.h>
#include <wx/filesys.h>
#include <wx/sizer.h>
#include <wx/stattext.h>
#include <wx/webview.h>

namespace Slic3r::GUI::JusPrin {

namespace {

// How long the page may take to load and complete the hello handshake before
// the internal-connection error is shown.
constexpr int kHandshakeDeadlineMs = 20000;

constexpr int kHandshakeTimerId = wxID_HIGHEST + 1802;

boost::filesystem::path agent_page_path()
{
    return boost::filesystem::path(resources_dir()) / "jusprin" / "agent" / "index.html";
}

wxString agent_page_url(AgentPageMode mode)
{
    wxString url;
    if (const char* dev = std::getenv("JUSPRIN_AGENT_DEV_URL"); dev != nullptr && *dev != '\0') {
        url = wxString::FromUTF8(dev);
    } else {
        const boost::filesystem::path page = agent_page_path();
        if (!boost::filesystem::exists(page))
            return {};
        url = wxFileSystem::FileNameToURL(wxFileName(wxString::FromUTF8(page.string())));
    }
    if (mode == AgentPageMode::PrinterPanel)
        url += "?panel=printer";
    else if (mode == AgentPageMode::Preferences)
        url += "?panel=preferences";
    else if (mode == AgentPageMode::OrcaImport)
        url += "?panel=orca-import";
    else if (mode == AgentPageMode::Guide)
        url += "?panel=guide";
    return url;
}

std::unique_ptr<Agent::ProjectPersistence> in_memory_document(Workspace::IWorkspace& workspace)
{
    Agent::ProjectPersistence::Config storage;
    storage.in_memory = true;
    return std::make_unique<Agent::ProjectPersistence>(workspace, std::move(storage));
}

} // namespace

AgentWebView::AgentWebView(wxWindow*                  parent,
                           const ShellTheme&          theme,
                           Workspace::IWorkspace&     workspace,
                           Agent::ProjectPersistence& persistence,
                           Agent::AgentAvailability   availability,
//                  carries; it asks the app only to open a link.
enum class AgentPageMode { Conversation, PrinterPanel, Preferences, OrcaImport, Guide };

class AgentWebView : public wxPanel
{
public:
    AgentWebView(wxWindow*                        parent,
                 const ShellTheme&                theme,
                 Workspace::IWorkspace&           workspace,
                 Agent::ProjectPersistence&       persistence,
                 Agent::AgentAvailability         availability,
                 Agent::AgentServicePtr            agent = {},
                 Agent::AgentSetupServicePtr       setup = {},
                 AgentPageMode                     mode = AgentPageMode::Conversation);
    // A view with a document of its own, in memory, never the project's:
    // for the windows that hold no chat, and for chats that go when their
    // window closes. host().persistence() reads it.
    AgentWebView(wxWindow*                   parent,
                 const ShellTheme&           theme,
                 Workspace::IWorkspace&      workspace,
                 Agent::AgentAvailability    availability,
                 Agent::AgentServicePtr      agent,
                 Agent::AgentSetupServicePtr setup,
                 AgentPageMode               mode);
    ~AgentWebView() override;

    void apply_appearance(bool dark);
    void reload();
    // When the shell temporarily gives this view the whole workspace, keep
    // its native error surface navigable even if the web bridge never loads.
    void set_error_fallback_actions(const wxString& return_label,
                                    const wxString& manual_label,
                                    std::function<void()> on_return,
                                    std::function<void()> on_manual);

    Agent::AgentHost&    host() { return *m_host; }
    // The docked project chat's model, provider and thinking pickers: keys
    // and lists from AppConfig and the providers. The printer panel's view
    // does not call it, so its photo composer shows no pickers.
    void enable_chat_model_choice(AppConfig* config);
    wxWebView*           webview() const { return m_webview; }
    bool                 bridge_error_shown() const { return m_error_panel != nullptr && m_error_panel->IsShown(); }

private:
    AgentWebView(wxWindow*                                  parent,
                 const ShellTheme&                          theme,
                 Workspace::IWorkspace&                     workspace,
                 Agent::ProjectPersistence*                 borrowed,
                 std::unique_ptr<Agent::ProjectPersistence> own_document,
                 Agent::AgentAvailability                   availability,
                 Agent::AgentServicePtr                     agent,
                 Agent::AgentSetupServicePtr                setup,
                 AgentPageMode                              mode);

    void on_script_message(wxWebViewEvent& event);
    void on_load_error(wxWebViewEvent& event);
    void on_handshake_deadline(wxTimerEvent& event);
    void show_bridge_error(const wxString& reason);
    void hide_bridge_error();
    wxString diagnostics_text(const wxString& reason) const;

    const ShellTheme&                 m_theme;
    // Before the host, which holds the document by reference: built first,
    // destroyed last.
    std::unique_ptr<Agent::ProjectPersistence> m_own_document;
    std::unique_ptr<Agent::AgentHost> m_host;
    wxWebView*                        m_webview{nullptr};

    wxPanel*      m_error_panel{nullptr};
    wxStaticText* m_error_title{nullptr};
    wxStaticText* m_error_detail{nullptr};
    Button*       m_retry_button{nullptr};
    Button*       m_return_button{nullptr};
    Button*       m_manual_button{nullptr};
    std::function<void()> m_on_error_return;
    std::function<void()> m_on_error_manual;

    wxTimer  m_handshake_timer;
    wxString m_page_url;
    wxString m_last_load_error;
};

} // namespace Slic3r::GUI::JusPrin

