// The local file a navigation would open, when it is not the page itself.
std::optional<wxString> dropped_file(const wxString& url)
{
    if (!url.Lower().StartsWith("file:"))
        return std::nullopt;
    // The page's own address may carry a query (?panel=printer); a file name
    // with a question mark in it arrives escaped.
    const wxFileName file = wxFileSystem::URLToFileName(url.BeforeFirst('?'));
    if (file.SameAs(wxFileName(wxString::FromUTF8(agent_page_path().string()))))
        return std::nullopt;
    return file.GetFullPath();
}

